\section*{Bayes' Theorem}

\begin{enumerate}[label=\arabic*-, leftmargin=*]
    \item \textbf{Finding predictive values}
    \item \textbf{Determine false positive and false negative, sensitivity and specificity}
    \item \textbf{Problem sets}
